#include "../driver/init_io.h"
#include <assert.h>
#include <stdio.h>
#include <string.h>

/* Literal synthetic table and port trace, derived from consumer/address
 * arithmetic and actual helper assembly, never generated by the component. */
#define ROW(o,w,v) (o)&255,((o)>>8)&255,(w)&255,((w)>>8)&255, \
    (v)&255,((v)>>8)&255,((v)>>16)&255,((v)>>24)&255
static const uint8_t table[] = {
    ROW(0x130,4,0xffffffffu), ROW(0x1000,0,0xa1b2c3d4u),
    ROW(0x12,2,0x12345678u), ROW(0x20,3,0),
    ROW(0xfffe,4,0xfeedbeefu), ROW(0xffff,0,0)
};
struct event { unsigned path; enum axd_d11_kind kind; uint32_t offset,value,reply; };
#define E(p,k,o,v,r) {AXD_INIT_IO_##p,AXD_D11_##k,o,v,r}
static const struct event expected[] = {
    E(DIRECT,STORE_BARRIER,0,0,0), E(DIRECT,WRITE32,0x130,1,0),
    E(OBJECT,STORE_BARRIER,0,0,0), E(OBJECT,WRITE32,0x160,0x30600,0),
    E(OBJECT,READ32,0x160,0,0x12345678), E(OBJECT,FULL_BARRIER,0,0,0),
    E(OBJECT,STORE_BARRIER,0,0,0), E(OBJECT,WRITE16,0x164,0xc3d4,0),
    E(DIRECT,STORE_BARRIER,0,0,0), E(DIRECT,WRITE16,0x12,0x5678,0),
    E(OBJECT,STORE_BARRIER,0,0,0), E(OBJECT,WRITE32,0x160,0x37dff,0),
    E(OBJECT,READ32,0x160,0,0x87654321), E(OBJECT,FULL_BARRIER,0,0,0),
    E(OBJECT,STORE_BARRIER,0,0,0), E(OBJECT,WRITE16,0x164,0xbeef,0)
};
struct fixture {
    struct axd_init_io *job;
    const struct event *script;
    size_t count;
    size_t seen,stop;
    unsigned error,cancel;
};
static int io(void *opaque,const struct axd_init_io_operation *op,uint32_t *read)
{
    struct fixture *f=opaque;
    const struct event *e;
    const struct event *script=f->script==NULL?expected:f->script;
    size_t count=f->script==NULL?sizeof(expected)/sizeof(expected[0]):f->count;
    assert(f->seen<count); e=&script[f->seen++];
    assert((unsigned)op->path==e->path && op->operation.kind==e->kind);
    assert(op->operation.offset==e->offset && op->operation.value==e->value);
    *read=e->reply;
    if(f->cancel && f->seen==f->stop) axd_init_io_cancel(f->job);
    return f->error && f->seen==f->stop ? -1:0;
}
static void run(struct axd_init_io *j,struct fixture *f)
{
    unsigned steps=0;
    f->job=j;
    while(j->phase==AXD_INIT_IO_RUNNING) {
        size_t before=f->seen;
        axd_init_io_step(j,io,f);
        assert(f->seen-before<=1 && ++steps<1000);
    }
    {
        size_t before=f->seen;
        enum axd_init_io_phase phase=j->phase;
        assert(axd_init_io_step(j,io,f)==phase);
        assert(axd_init_io_cancel(j)==phase && before==f->seen);
    }
}
static struct axd_init_io_request request(const uint32_t *addend)
{
    const struct axd_init_io_request r={table,sizeof(table),addend,0x1000,0x20000};
    return r;
}
static void mixed_and_exits(void)
{
    struct axd_init_io j;
    struct axd_object_context c={130,1,1};
    uint32_t addend=2;
    struct axd_init_io_request r=request(&addend);
    struct fixture f={0};
    unsigned mode;size_t p;
    assert(axd_init_io_begin(&j,&r,&c)==0);run(&j,&f);
    assert(j.phase==AXD_INIT_IO_DONE && f.seen==16);
    assert(j.completed_records==5 && j.skipped_records==1);
    assert(j.completed_ops==16 && j.attempted_ops==16 && j.object.completed_bytes==2);
    assert(j.effective.completed_ops==6); /* Four direct events + two semantic copies. */
    for(p=1;p<=16;p++)for(mode=1;mode<=3;mode++) {
        memset(&f,0,sizeof(f));f.stop=p;f.error=mode&1;f.cancel=(mode>>1)&1;
        assert(axd_init_io_begin(&j,&r,&c)==0);run(&j,&f);
        assert(f.seen==p && j.attempted_ops==p && j.completed_ops==p-f.error);
        assert(j.phase==(f.error?AXD_INIT_IO_FAILED:AXD_INIT_IO_CANCELLED));
        assert(j.error==(f.error?AXD_INIT_IO_CALLBACK_ERROR:AXD_INIT_IO_NO_ERROR));
        if(p==8 || p==16) {
            assert(j.object.completed_bytes==(f.error?0u:2u));
            assert(j.completed_records==(p==8?1u:4u));
        }
    }
    assert(axd_init_io_begin(&j,&r,&c)==0);
    assert(axd_init_io_begin(&j,&j.request,&j.context)==0 && j.addend==2);
    memset(&f,0,sizeof(f));run(&j,&f);assert(j.completed_records==5);
    assert(axd_init_io_begin(&j,&j.request,&j.context)==0);
    assert(axd_init_io_cancel(&j)==AXD_INIT_IO_CANCELLED);
    memset(&f,0,sizeof(f));run(&j,&f);assert(f.seen==0);
}
static void reached_dependencies_and_validation(void)
{
    struct axd_init_io j;
    struct axd_object_context c={130,1,0};
    uint32_t addend=2;
    struct axd_init_io_request r=request(&addend);
    struct fixture f={0};
    static const uint8_t empty[]={ROW(0xffff,0,0)};
    static const uint8_t only_object[]={ROW(0x1000,4,0),ROW(0xffff,0,0)};
    uint8_t bad[sizeof(table)];
    assert(axd_init_io_begin(&j,&r,&c)==0);run(&j,&f);
    assert(j.phase==AXD_INIT_IO_DEPENDENCY && f.seen==0 && j.completed_records==0);
    r.data=only_object;r.length=sizeof(only_object);
    assert(axd_init_io_begin(&j,&r,&c)==0);run(&j,&f);
    assert(j.phase==AXD_INIT_IO_DEPENDENCY && j.completed_records==0);
    assert(j.effective.completed_records==1 && j.object.completed_bytes==0);
    r.data=empty;r.length=sizeof(empty);r.offset130_addend=NULL;
    assert(axd_init_io_begin(&j,&r,&c)==0 && j.phase==AXD_INIT_IO_DONE);
    r=request(NULL);c.owned=1;
    assert(axd_init_io_begin(&j,&r,&c)!=0 && j.error==AXD_INIT_IO_TABLE_ERROR);
    r=request(&addend);memcpy(bad,table,sizeof(bad));bad[16]=0x11;r.data=bad;
    assert(axd_init_io_begin(&j,&r,&c)!=0 && j.attempted_ops==0);
    r=request(&addend);r.object_window=0x1f7fd;
    assert(axd_init_io_begin(&j,&r,&c)!=0 && j.attempted_ops==0);
    assert(axd_init_io_begin(NULL,&r,&c)!=0);
    assert(axd_init_io_begin(&j,NULL,&c)!=0);
    assert(axd_init_io_begin(&j,&r,NULL)!=0);
    assert(axd_init_io_step(NULL,io,&f)==AXD_INIT_IO_INVALID);
    assert(axd_init_io_cancel(NULL)==AXD_INIT_IO_INVALID);
}
static void skipped_alias_and_final_direct(void)
{
    static const uint8_t skipped[]={ROW(0x130,0,0),ROW(0xffff,0,0)};
    static const uint8_t aliases[]={ROW(0x1000,4,0x1234),ROW(0x1001,2,0x5678),ROW(0xffff,0,0)};
    static const uint8_t direct[]={ROW(0x12,2,0xabcd),ROW(0xffff,0,0)};
    static const struct event repeated[]={
        E(OBJECT,STORE_BARRIER,0,0,0),E(OBJECT,WRITE32,0x160,0x30600,0),
        E(OBJECT,READ32,0x160,0,0x1000),E(OBJECT,FULL_BARRIER,0,0,0),
        E(OBJECT,STORE_BARRIER,0,0,0),E(OBJECT,WRITE16,0x164,0x1234,0),
        E(OBJECT,STORE_BARRIER,0,0,0),E(OBJECT,WRITE32,0x160,0x30600,0),
        E(OBJECT,READ32,0x160,0,0x9000),E(OBJECT,FULL_BARRIER,0,0,0),
        E(OBJECT,STORE_BARRIER,0,0,0),E(OBJECT,WRITE16,0x164,0x5678,0)
    };
    static const struct event last[]={E(DIRECT,STORE_BARRIER,0,0,0),E(DIRECT,WRITE16,0x12,0xabcd,0)};
    struct axd_init_io j;struct axd_object_context c={130,1,0};
    struct axd_init_io_request r={skipped,sizeof(skipped),NULL,0x1000,0x20000};
    struct fixture f={0};
    assert(axd_init_io_begin(&j,&r,&c)==0);run(&j,&f);
    assert(j.phase==AXD_INIT_IO_DONE && j.skipped_records==1 && !f.seen);
    c.owned=1;r.data=aliases;r.length=sizeof(aliases);
    f.script=repeated;f.count=sizeof(repeated)/sizeof(repeated[0]);
    assert(axd_init_io_begin(&j,&r,&c)==0);run(&j,&f);
    assert(j.phase==AXD_INIT_IO_DONE && j.completed_records==2 && f.seen==12);
    r.data=direct;r.length=sizeof(direct);memset(&f,0,sizeof(f));
    f.script=last;f.count=2;f.stop=2;f.cancel=1;
    assert(axd_init_io_begin(&j,&r,&c)==0);run(&j,&f);
    assert(j.phase==AXD_INIT_IO_CANCELLED && j.completed_records==1 && j.completed_ops==2);
}
int main(void)
{
    mixed_and_exits();reached_dependencies_and_validation();skipped_alias_and_final_direct();
    puts("initialization physical lowering: literal direct/object ports, bounds, aliases and every callback exit passed");
    return 0;
}
